121	function correctHours(time) {
122	  const { afternoon } = time
123	  if (afternoon !== undefined) {
124	    const { hours } = time
125	    if (afternoon) {
126	      if (hours < 12) {
127	        time.hours += 12
128	      }
129	    } else if (hours === 12) {
130	      time.hours = 0
131	    }
132	    delete time.afternoon
133	  }
134	}
