136	function makeParser(format) {
137	  const array = format.match(formattingTokens)
138	  const { length } = array
139	  for (let i = 0; i < length; i += 1) {
140	    const token = array[i]
141	    const parseTo = expressions[token]
142	    const regex = parseTo && parseTo[0]
143	    const parser = parseTo && parseTo[1]
144	    if (parser) {
145	      array[i] = { regex, parser }
146	    } else {
147	      array[i] = token.replace(/^\[|\]$/g, '')
148	    }
149	  }
150	  return function (input) {
151	    const time = {}
152	    for (let i = 0, start = 0; i < length; i += 1) {
153	      const token = array[i]
154	      if (typeof token === 'string') {
155	        start += token.length
156	      } else {
157	        const { regex, parser } = token
158	        const part = input.substr(start)
159	        const match = regex.exec(part)
160	        const value = match[0]
161	        parser.call(time, value)
162	        input = input.replace(value, '')
163	      }
164	    }
165	    correctHours(time)
166	    return time
167	  }
168	}
