170	const parseFormattedInput = (input, format, utc) => {
171	  try {
172	    const parser = makeParser(format)
173	    const {
174	      year, month, day, hours, minutes, seconds, milliseconds, zone
175	    } = parser(input)
176	    const now = new Date()
177	    const d = day || ((!year && !month) ? now.getDate() : 1)
178	    const y = year || now.getFullYear()
179	    let M = 0
180	    if (!(year && !month)) {
181	      M = month > 0 ? month - 1 : now.getMonth()
182	    }
183	    const h = hours || 0
184	    const m = minutes || 0
185	    const s = seconds || 0
186	    const ms = milliseconds || 0
187	    if (zone) {
188	      return new Date(Date.UTC(y, M, d, h, m, s, ms + (zone.offset * 60 * 1000)))
189	    }
190	    if (utc) {
191	      return new Date(Date.UTC(y, M, d, h, m, s, ms))
192	    }
193	    return new Date(y, M, d, h, m, s, ms)
194	  } catch (e) {
195	    return new Date('') // Invalid Date
196	  }
197	}
